// swift-tools-version: 5.10
import PackageDescription

// Mercury's shared Rust voice engine (crates/mercury-voice-mobile): the same
// voice links Optimus runs on the desktop. MercuryVoiceFFI.xcframework is
// built by ../scripts/build-voice-engine.sh (not committed); MercuryVoice.swift
// is generated by the same script from the Rust crate (committed).
let package = Package(
  name: "MercuryVoice",
  platforms: [.iOS(.v17), .macOS(.v14)],
  products: [
    .library(name: "MercuryVoice", targets: ["MercuryVoice"]),
  ],
  targets: [
    .binaryTarget(name: "MercuryVoiceFFI", path: "MercuryVoiceFFI.xcframework"),
    .target(name: "MercuryVoice", dependencies: ["MercuryVoiceFFI"], path: "Sources/MercuryVoice"),
  ]
)
